bDriveEnableStatus1 := TRUE;
bDriveEnableStatus2 := TRUE;
bDriveEnableStatus3 := TRUE;
bDriveEnableStatus4 := TRUE;
bDriveEnableStatus5 := TRUE;
bDriveEnableStatus6 := TRUE;
bDriveEnableStatus7 := TRUE;
bDriveEnableStatus8 := TRUE;
bDriveEnableStatus9 := TRUE;

IF AxisNumber >= 0 THEN
  ServoEnableControl_0(
       bDriveReset := g_bplcHardwareResetBuffer,
       bEnable := bDriveControl[0],
       nStatusWord := g_niStatusWord0,
       nControlWord => g_noControlWord0,
       bDriveError => bDriveError0,
       bAxisEnableStatus => bDriveEnableStatus0 );
	  IF(bDriveError0) THEN
		g_Alarm.alarmArray[19] := 719;
      END_IF;
END_IF;
