(*只要上了使能就把抱闸都打开,不用就不配*)
FTrrigerPowerOff(CLK := g_bDriveEnable);
 RTrrigerPowerON(CLK := g_bDriveEnable);

IF RTrrigerPowerON.Q THEN
  nPowerId := 100;
  TonDelayBrakeOpen(IN := FALSE);
ELSIF FTrrigerPowerOff.Q THEN
  TonDelayBrakeOpen(IN := FALSE);
  nPowerId := 200;
END_IF;
  (*轴下使能逻辑：先抱闸,延时100s，下使能*)
case nPowerId OF
      0:
      ;
    100:
      TonDelayBrakeOpen(IN := TRUE, PT := T#800ms);   
      IF TonDelayBrakeOpen.Q THEN
        g_boCNCAAxisHoldBrake := TRUE;(*只要驱动器上使能了，就解除抱闸*)
        g_boCNCXAxisHoldBrake := TRUE;
        g_boCNCYAxisHoldBrake := TRUE;
        g_boCNCUAxisHoldBrake := TRUE;
        nPowerId := 0;
        TonDelayBrakeOpen(IN:=FALSE);
      END_IF;    
    200:
         g_boCNCXAxisHoldBrake := FALSE;
        g_boCNCYAxisHoldBrake := FALSE;
        g_boCNCUAxisHoldBrake := FALSE;
        g_boCNCAAxisHoldBrake := FALSE;
           nPowerId := 0;
END_CASE;







Ton_timeCheckEnable(IN := TRUE,PT := T#400ms);
IF Ton_timeCheckEnable.Q THEN
	Ton_timeCheckEnable(IN := FALSE);
	IF NOT bDriveEnableStatus0 THEN
	  g_Alarm.alarmArray[152] := 855;
      IF CNCAxisConfig[0] = 1 THEN
			g_boCNCXAxisHoldBrake := FALSE;
